mapper.select:
select *
from sys_schedule_task
where updated_time >= #{startTime}
and updated_time <= #{endTime}

mapper.update:
update sys_schedule_task
set loop_count=#{loopCount}
where task_id=#{taskId}

UPDATE sys_schedule_task SET quartz_sync_status=#{syncStatus}, quartz_sync_message=#{message},
  quartz_synced_at=COALESCE(#{syncedAt},quartz_synced_at)
WHERE task_id=#{taskId} AND row_version=#{rowVersion} AND task_status=#{taskStatus}
